#!/usr/bin/env bash
# valkey instances: one Valkey process per app, each with its own TLS port,
# password, memory cap and redis_exporter (ADR 0016). Run by OpenTofu
# (terraform_data.valkey_instances) after setup.sh.
#
#   instances.sh <listen-ip>
# stdin, one line per app (generated by proxmox/opentofu/valkey.tf):
#   <app> <port> <exporter port> <maxmemory> <maxmemory-policy> <password> [<reader>=<password> ...]
#
# An instance is restarted only when its config changed (a restart empties
# its cache); a change to its read-only users alone is applied to the running
# instance instead (ACL SETUSER / DELUSER). An app no longer listed is stopped
# and its config removed: a cache holds nothing to keep.
set -euo pipefail

IP=${1:?usage: instances.sh <listen-ip>}
CERT=/etc/valkey/tls/cert.pem   # tls.sh (OpenTofu): the CT's name and IP, pinnable
KEY=/etc/valkey/tls/key.pem
# People's read-only users (ADR 0029): read commands only, keys read-only, no
# pub/sub, nothing @dangerous (KEYS, FLUSHALL, MONITOR, CONFIG, DEBUG, CLIENT
# KILL) except INFO, which GUI clients ask for.
READ_ONLY_RULES=(resetkeys '%R~*' resetchannels -@all +@read +@connection -@dangerous +info)

wanted=()
while read -r app port eport maxmem policy pw readers; do
  [ -n "$app" ] || continue
  [[ $app =~ ^[a-z][a-z0-9_-]{0,40}$ ]] || { echo "bad app name: $app" >&2; exit 1; }
  [[ $port =~ ^[0-9]{4,5}$ && $eport =~ ^[0-9]{4,5}$ ]] || { echo "bad ports for $app" >&2; exit 1; }
  [[ $maxmem =~ ^[0-9]+(mb|gb)$ ]] || { echo "bad maxmemory for $app" >&2; exit 1; }
  [[ $policy =~ ^(volatile|allkeys)-(lru|lfu|random|ttl)$|^noeviction$ ]] || { echo "bad policy for $app" >&2; exit 1; }
  [[ $pw =~ ^[A-Za-z0-9]{24,}$ ]] || { echo "bad password for $app" >&2; exit 1; }
  wanted+=("$app")

  users='' names=() hashes=()
  for r in $readers; do
    rname=${r%%=*} rpw=${r#*=}
    [[ $rname =~ ^${app}_[a-z0-9_]+$ ]] || { echo "bad reader name for $app" >&2; exit 1; }
    [[ $rpw =~ ^[A-Za-z0-9]{24,}$ ]] || { echo "bad password for reader $rname" >&2; exit 1; }
    rhash=$(printf '%s' "$rpw" | sha256sum | cut -d' ' -f1)
    users+="user ${rname} on #${rhash} ${READ_ONLY_RULES[*]}"$'\n'
    names+=("$rname") hashes+=("$rhash")
  done

  conf=/etc/valkey/valkey-${app}.conf
  tmp=$(mktemp "/etc/valkey/.valkey-${app}.XXXXXX")
  cat > "$tmp" <<EOF
# managed by services/valkey/instances.sh (OpenTofu) — do not edit
# ${app}: a cache (no persistence), TLS only, its own password and memory cap.
bind ${IP}
port 0
tls-port ${port}
tls-cert-file ${CERT}
tls-key-file ${KEY}
tls-auth-clients no
unixsocket /run/valkey-${app}/valkey.sock
unixsocketperm 770
pidfile /run/valkey-${app}/valkey-server.pid
requirepass "${pw}"
maxmemory ${maxmem}
maxmemory-policy ${policy}
save ""
appendonly no
dir /var/lib/valkey/${app}
logfile ""
EOF
  printf '%s' "$users" >> "$tmp"
  chown root:valkey "$tmp"
  chmod 0640 "$tmp"
  install -d -o valkey -g valkey -m 0750 "/var/lib/valkey/${app}"

  env=/etc/redis-exporter/${app}.env
  etmp=$(mktemp "/etc/redis-exporter/.${app}.XXXXXX")
  printf 'REDIS_ADDR=unix:///run/valkey-%s/valkey.sock\nREDIS_PASSWORD=%s\nREDIS_EXPORTER_WEB_LISTEN_ADDRESS=%s:%s\n' "$app" "$pw" "$IP" "$eport" > "$etmp"
  chown root:prometheus "$etmp"
  chmod 0640 "$etmp"

  changed=0 users_changed=0
  cmp -s <(grep -v '^user ' "$tmp") <(grep -v '^user ' "$conf" 2>/dev/null) || changed=1
  cmp -s "$etmp" "$env" || changed=1
  cmp -s <(grep '^user ' "$tmp") <(grep '^user ' "$conf" 2>/dev/null) || users_changed=1
  mv "$tmp" "$conf"
  mv "$etmp" "$env"
  systemctl enable -q "valkey-server@${app}" "redis-exporter@${app}"
  vcli() { REDISCLI_AUTH="$pw" valkey-cli -s "/run/valkey-${app}/valkey.sock" "$@"; }
  if [ "$changed" = 1 ] || ! systemctl is-active -q "valkey-server@${app}"; then
    systemctl restart "valkey-server@${app}"
    systemctl restart "redis-exporter@${app}"
  elif [ "$users_changed" = 1 ]; then
    # Users only: the running instance takes them as they are in the config,
    # and keeps its cache. A user no longer declared is deleted, which also
    # closes its connections.
    for i in "${!names[@]}"; do
      [ "$(vcli ACL SETUSER "${names[$i]}" reset on "#${hashes[$i]}" "${READ_ONLY_RULES[@]}")" = OK ] \
        || { echo "valkey ${app}: ACL SETUSER ${names[$i]} failed" >&2; exit 1; }
    done
    for u in $(vcli ACL USERS); do
      [ "$u" = default ] || [[ " ${names[*]} " == *" ${u} "* ]] || vcli ACL DELUSER "$u" >/dev/null
    done
  fi
  # a no-op when running; brings back one that stopped (a failed boot)
  systemctl start "valkey-server@${app}" "redis-exporter@${app}"

  for _ in $(seq 1 20); do
    [ "$(REDISCLI_AUTH="$pw" valkey-cli --tls --insecure -h "$IP" -p "$port" ping 2>/dev/null)" = PONG ] && break
    sleep 1
  done
  [ "$(REDISCLI_AUTH="$pw" valkey-cli --tls --insecure -h "$IP" -p "$port" ping 2>/dev/null)" = PONG ] || { echo "valkey-server@${app} does not answer on ${port}" >&2; exit 1; }
  for _ in $(seq 1 15); do
    curl -fsS "http://${IP}:${eport}/metrics" 2>/dev/null | grep "^redis_up 1" >/dev/null && break
    sleep 1
  done
  curl -fsS "http://${IP}:${eport}/metrics" | grep "^redis_up 1" >/dev/null || { echo "redis-exporter@${app} reports the instance down" >&2; exit 1; }
  # Each reader may read and may not write (checked against the live rules).
  for rname in "${names[@]}"; do
    [ "$(vcli ACL DRYRUN "$rname" GET probe)" = OK ] && [ "$(vcli ACL DRYRUN "$rname" SET probe 1)" != OK ] \
      || { echo "valkey ${app}: reader ${rname} does not have read-only rules" >&2; exit 1; }
  done
  echo "valkey ${app}: tls port ${port}, exporter ${eport}, maxmemory ${maxmem}$([ "$changed" = 1 ] && echo ' (restarted)')${names[*]:+, read-only: ${names[*]}}$([ "$changed" = 0 ] && [ "$users_changed" = 1 ] && echo ' (users applied live)')"
done
[ ${#wanted[@]} -gt 0 ] || { echo "no instances on stdin" >&2; exit 1; }

# Instances no longer listed.
for conf in /etc/valkey/valkey-*.conf; do
  [ -e "$conf" ] || continue
  app=${conf#/etc/valkey/valkey-}; app=${app%.conf}
  keep=0
  for w in "${wanted[@]}"; do [ "$w" = "$app" ] && keep=1; done
  [ "$keep" = 1 ] && continue
  systemctl disable -q --now "redis-exporter@${app}" "valkey-server@${app}" 2>/dev/null || true
  rm -f "$conf" "/etc/redis-exporter/${app}.env"
  echo "valkey ${app}: removed (no longer listed)"
done
